#!/usr/bin/env bash
# Phase 4 measurements (docs/phase4-design.md): every workload under every
# config on the Release simulator, with pass + lockstep checks, a determinism
# re-run, and generated tables.
#
#   scripts/phase4_run.sh
#
# Writes:
#   results/phase4/stats/<config>/<workload>.json   rvsim-pipe --stats (incl. "roi")
#   results/phase4/profiles/<workload>.txt          retired-instruction count per pc in the ROI
#   results/phase4/status.txt                       per run: pass + lockstep exit codes
#   results/phase4/raw.csv, tables.md               generated by scripts/phase4_tables.py
set -euo pipefail
cd "$(dirname "$0")/.."
prov=$(scripts/env_report.sh)   # provenance first (docs/BUGS.md #2)
start=$(date +%s)

b=build/release
rm -rf "$b"
cmake --preset release > /dev/null
cmake --build --preset release > /dev/null

out=results/phase4
rm -rf "$out"
mkdir -p "$out/stats" "$out/profiles"
CONFIGS="baseline bimodal_btb gshare_btb small_caches big"

export B="$b" OUT="$out"
run_one() {  # $1 = workload elf, $2 = config name
  local elf=$1 cfg=$2 name
  name=$(basename "$elf" .elf)
  mkdir -p "$OUT/stats/$cfg"
  local prc=0 lrc=0
  "$B/rvsim-pipe" "$elf" --config "configs/$cfg.cfg" --stats "$OUT/stats/$cfg/$name.json" 2>/dev/null || prc=$?
  "$B/rvsim-lockstep" "$elf" --config "configs/$cfg.cfg" > /dev/null 2>&1 || lrc=$?
  echo "$name $cfg pass_rc=$prc lockstep_rc=$lrc"
}
export -f run_one

elfs=$(ls "$b"/workloads/*.elf | sort)
for e in $elfs; do for c in $CONFIGS; do echo "$e $c"; done; done \
  | xargs -P "$(nproc)" -n 2 bash -c 'run_one "$0" "$1"' | sort > "$out/status.txt"

# The per-pc retirement profile does not depend on timing, so one config suffices.
for e in $elfs; do
  "$b/rvsim-pipe" "$e" --config configs/baseline.cfg --pc-profile "$out/profiles/$(basename "$e" .elf).txt" 2>/dev/null
done

# Determinism: re-run a fixed sample and require byte-identical stats.
det_ok=0
det_n=0
for spec in "asm-gemm_tiled-n64 small_caches" "c-O3-gemm_naive-n32 big" "asm-dot_naive-n1024 gshare_btb" \
            "c-O0-gemm_tiled-n64 small_caches" "asm-gemm_unroll4-n32 bimodal_btb"; do
  set -- $spec
  det_n=$((det_n + 1))
  "$b/rvsim-pipe" "$b/workloads/$1.elf" --config "configs/$2.cfg" --stats /tmp/rvx_det.json 2>/dev/null || true
  cmp -s /tmp/rvx_det.json "$out/stats/$2/$1.json" && det_ok=$((det_ok + 1))
done

runs=$(wc -l < "$out/status.txt")
good=$(grep -c 'pass_rc=0 lockstep_rc=0' "$out/status.txt" || true)
elapsed=$(( $(date +%s) - start ))
{
  echo "# Phase 4 measurement run"
  echo "command: scripts/phase4_run.sh"
  echo
  echo "## Provenance"
  echo "$prov"
  echo
  echo "## Run summary"
  echo "workloads: $(echo "$elfs" | wc -l), configs: $(echo $CONFIGS | wc -w), runs: $runs"
  echo "runs where the workload passed its own result check AND lockstep agreed: $good of $runs"
  echo "determinism re-runs with byte-identical stats: $det_ok of $det_n"
  echo "wall time for this script (build + all runs + profiles + re-runs): ${elapsed} s"
} > "$out/run_summary.txt"

python3 scripts/phase4_tables.py "$out" "$b/workloads" > /dev/null
python3 scripts/phase4_investigations.py "$b" "$out/investigations.md" > /dev/null
# Rule 1: every measurement quoted in RESULTS.md must appear in a generated file.
# (Checks against Phase 4 and, if present, Phase 6 sweep results.)
if [ -f RESULTS.md ]; then
  bash scripts/check_results.sh > "$out/results_check.txt" 2>&1 || true
  cat "$out/results_check.txt"
fi
cat "$out/run_summary.txt"
